import{_ as r,c as a,o,a5 as t}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"搜索后端与查询归一化","description":"","frontmatter":{"title":"搜索后端与查询归一化","date":"2026-05-24T00:00:00.000Z","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#6.2","branch":"main","level":1,"order":6.2},"headers":[],"relativePath":"posts/projects/zfeed/06-search-rpc-service/02-search-backend-and-query-normalization.md","filePath":"posts/projects/zfeed/06-search-rpc-service/02-search-backend-and-query-normalization.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/06-search-rpc-service/02-search-backend-and-query-normalization.md"};function i(n,e,p,l,s,h){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="搜索后端与查询归一化" tabindex="-1">搜索后端与查询归一化 <a class="header-anchor" href="#搜索后端与查询归一化" aria-label="Permalink to &quot;搜索后端与查询归一化&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend.go" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/mysql.go" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/mysql.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/cache.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/cache.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go</a></li></ul></details><p><code>search-rpc</code> 服务使用多层搜索策略，当前主要由 MySQL 支撑。它引入查询归一化以保证缓存一致性，并使用 MySQL Full-Text Search（FTS）能力；如果 FTS 没有结果或不可用，则回退到 <code>LIKE</code> 模式，以提升兼容性和可靠性。</p><h2 id="查询归一化" tabindex="-1">查询归一化 <a class="header-anchor" href="#查询归一化" aria-label="Permalink to &quot;查询归一化&quot;">​</a></h2><p>在任何搜索落到数据库或缓存之前，原始输入字符串都会先由 <code>DefaultNormalizer</code> 处理。这样可以避免用户输入中的细微差异（例如额外空格、大小写差异）生成冗余缓存条目或不一致的搜索结果。</p><h3 id="归一化流程" tabindex="-1">归一化流程 <a class="header-anchor" href="#归一化流程" aria-label="Permalink to &quot;归一化流程&quot;">​</a></h3><ol><li>裁剪：移除首尾空白。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L35-L35" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#35</a></li><li>规范化：将字符串转换为小写，并把内部连续空白折叠为单个空格。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L36-L36" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#36</a></li><li>哈希：基于规范化字符串生成短 SHA-256 哈希（前 8 字节），作为缓存 key 标识符。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L45-L45" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#45</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L50-L53" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#50-53</a></li><li>日志脱敏：为保护用户隐私（例如搜索手机号），包含 7 个或更多数字的查询会在日志中被掩码为 <code>[numeric-query]</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L55-L66" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#55-66</a></li></ol><h3 id="数据结构-querynorm-query" tabindex="-1">数据结构：<code>querynorm.Query</code> <a class="header-anchor" href="#数据结构-querynorm-query" aria-label="Permalink to &quot;数据结构：`querynorm.Query`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>Raw</code></td><td>用户输入的原始字符串。</td></tr><tr><td><code>SearchText</code></td><td>裁剪后的输入，用于数据库查询。</td></tr><tr><td><code>Canonical</code></td><td>小写且空白折叠后的版本，用于哈希。</td></tr><tr><td><code>Hash</code></td><td>16 字符十六进制字符串，用于 Redis key。</td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/querynorm/normalizer.go#L12-L48" target="_blank" rel="noreferrer">app/rpc/search/internal/querynorm/normalizer.go#12-48</a></p><h2 id="搜索后端抽象" tabindex="-1">搜索后端抽象 <a class="header-anchor" href="#搜索后端抽象" aria-label="Permalink to &quot;搜索后端抽象&quot;">​</a></h2><p>系统使用 <code>Factory</code> 模式管理搜索后端。虽然当前实现主要使用 MySQL，但架构被设计为支持未来的搜索引擎（代码中称为 <code>engine</code>）。</p><h3 id="backend-factory-逻辑" tabindex="-1">Backend Factory 逻辑 <a class="header-anchor" href="#backend-factory-逻辑" aria-label="Permalink to &quot;Backend Factory 逻辑&quot;">​</a></h3><p><code>backend.Factory</code> 根据配置决定使用哪种实现。</p><ul><li>配置后端：通过环境变量/配置设置，例如 <code>mysql</code> 或 <code>engine</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend.go#L45-L57" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend.go#45-57</a></li><li>有效后端：如果配置为 <code>engine</code> 但尚未实现，则默认使用 <code>mysql</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend.go#L47-L50" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend.go#47-50</a></li></ul><h3 id="搜索后端流程" tabindex="-1">搜索后端流程 <a class="header-anchor" href="#搜索后端流程" aria-label="Permalink to &quot;搜索后端流程&quot;">​</a></h3><p>标题：搜索后端解析与执行</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/backend.go#L17-L69" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/backend.go#17-69</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/backend/mysql.go#L11-L50" target="_blank" rel="noreferrer">app/rpc/search/internal/backend/mysql.go#11-50</a></p><h2 id="mysql-全文搜索与计分" tabindex="-1">MySQL 全文搜索与计分 <a class="header-anchor" href="#mysql-全文搜索与计分" aria-label="Permalink to &quot;MySQL 全文搜索与计分&quot;">​</a></h2><p><code>searchRepositoryImpl</code> 实现两阶段搜索：先尝试高性能全文搜索，如果 FTS 返回空结果或不可用，则回退到标准 <code>LIKE</code> 查询。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L90-L119" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#90-119</a></p><h3 id="用户搜索" tabindex="-1">用户搜索 <a class="header-anchor" href="#用户搜索" aria-label="Permalink to &quot;用户搜索&quot;">​</a></h3><p>用户搜索面向 <code>nickname</code>、<code>bio</code> 和 <code>mobile</code> 列。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L132-L132" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#132</a></p><ul><li>Boolean Mode：归一化器会将查询转换为兼容 boolean mode 的字符串，例如添加 <code>*</code> 以支持前缀匹配。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L123-L132" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#123-132</a></li><li>回退：如果 FTS 失败，则在相同字段上使用 <code>%query%</code> LIKE 模式。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L100-L105" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#100-105</a></li></ul><h3 id="内容搜索与计分" tabindex="-1">内容搜索与计分 <a class="header-anchor" href="#内容搜索与计分" aria-label="Permalink to &quot;内容搜索与计分&quot;">​</a></h3><p>内容搜索更复杂，会联接 <code>zfeed_content</code>、<code>zfeed_article</code> 和 <code>zfeed_video</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L193-L223" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#193-223</a> 它会计算三类分数来确定相关性：</p><table tabindex="0"><thead><tr><th>分数类型</th><th>计算逻辑</th></tr></thead><tbody><tr><td>Text Score</td><td>查询精确匹配标题时提升 30 分，以标题开头时提升 20 分，出现在标题中时提升 10 分；描述匹配获得较低提升 5 分。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L204-L210" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#204-210</a></td></tr><tr><td>Hot Score</td><td>直接来自 <code>zfeed_content</code> 的 <code>hot_score</code> 列，表示历史互动热度。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L203-L203" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#203</a></td></tr><tr><td>Rank Score</td><td><code>Text Score</code> 与 <code>Hot Score</code> 之和，用于 “Relevance” 和 “Hybrid” 搜索模式。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L211-L217" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#211-217</a></td></tr></tbody></table><h3 id="搜索模式" tabindex="-1">搜索模式 <a class="header-anchor" href="#搜索模式" aria-label="Permalink to &quot;搜索模式&quot;">​</a></h3><p>系统通过 <code>mode</code> 参数支持不同排序策略。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L171-L171" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#171</a></p><ol><li>Latest：按 <code>published_at DESC</code> 排序。</li><li>Relevance：按 <code>rank_score DESC</code> 排序。</li><li>Hybrid：相关性与热度的加权组合（具体实现随 repository 方法而定）。</li></ol><p>标题：内容搜索数据流与计分</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L48-L60" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#48-60</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L169-L223" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#169-223</a></p><h2 id="分页与元信息" tabindex="-1">分页与元信息 <a class="header-anchor" href="#分页与元信息" aria-label="Permalink to &quot;分页与元信息&quot;">​</a></h2><p>搜索结果会携带 <code>SearchMeta</code>，用于指示内部实际采用的数据读取路径，例如 <code>fulltext</code>、<code>like</code> 或 <code>none</code>。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L26-L29" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#26-29</a></p><p>分页通过 <code>cursor</code> 处理，通常是上一页最后一项的 ID，用于在新内容持续发布时维持较稳定的结果。<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L107-L111" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#107-111</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L134-L137" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#134-137</a></p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L83-L119" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#83-119</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/repositories/search_repository.go#L121-L140" target="_blank" rel="noreferrer">app/rpc/search/internal/repositories/search_repository.go#121-140</a></p>',35)])])}const g=r(c,[["render",i]]);export{b as __pageData,g as default};
